    assert result == 65, f"Expected 65, got {result}"

def test_sum_empty():
    result = exercise.sum_numbers([])
    assert result == 0, f"Expected 0 for empty list, got {result}"

def test_sum_single():
    result = exercise.sum_numbers([42])
    assert result == 42, f"Expected 42, got {result}"

def test_sum_negatives():
    result = exercise.sum_numbers([-5, 10, -3])
    assert result == 2, f"Expected 2, got {result}"

