solution_code:
def filter_evens(numbers):
    evens = []
    for n in numbers:
        if n % 2 == 0:
            evens.append(n)
    return evens

test_suite:
def test_mixed_numbers():
    result = exercise.filter_evens([3, 8, 12, 7, 10, 5, 18])
    assert result == [8, 12, 10, 18], f"Expected [8, 12, 10, 18], got {result}"

def test_all_odd():
    result = exercise.filter_evens([1, 3, 5])
    assert result == [], f"Expected empty list, got {result}"

def test_all_even():
    result = exercise.filter_evens([2, 4, 6, 8])
    assert result == [2, 4, 6, 8], f"Expected [2, 4, 6, 8], got {result}"

def test_empty():
    result = exercise.filter_evens([])
    assert result == [], f"Expected empty list, got {result}"

